#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Plumo's release credentials: the Developer ID certificate that signs the
# app, the App Store Connect API key that notarizes it, and the updater key
# that signs each Update. Every secret goes straight into the repository's
# GitHub Actions secrets (the names `.github/workflows/release.yml` reads);
# nothing is written to a .env file. See docs/releasing.md.

REPO="aimeritething/Plumo"
UPDATER_KEY_PATH="$HOME/.tauri/plumo-updater.key"

# _identity: the Developer ID Application identity in the login keychain, e.g.
# "Developer ID Application: Jane Doe (ABCDE12345)". Empty when there is none.
_identity() {
  security find-identity -v -p codesigning 2>/dev/null \
    | sed -n 's/.*"\(Developer ID Application: [^"]*\)".*/\1/p' | head -n1
}

# _ask_file VAR "Prompt" DEFAULT: a path to an existing file, ~ expanded.
_ask_file() {
  local var="$1" prompt="$2" default="$3" input
  while true; do
    printf '  %s%s%s %s[Enter for %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$default" "$RESET"
    read -r input || true
    [[ -z "$input" ]] && input="$default"
    input="${input/#\~/$HOME}"
    if [[ -f "$input" ]]; then printf -v "$var" '%s' "$input"; return 0; fi
    warn "no file at $input"
  done
}

run_wizard() {

TOTAL_STAGES=6

banner "Plumo release credentials"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "Secrets are written to the GitHub repository $REPO."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "The GitHub CLI is missing or signed out. Run 'gh auth login', then run this wizard again."
  exit 1
fi
if [[ "$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null)" != "$REPO" ]]; then
  warn "Run this wizard from a checkout of $REPO."
  exit 1
fi
if [[ ! -x node_modules/.bin/tauri ]]; then
  warn "The Tauri CLI is not installed. Run 'pnpm install', then run this wizard again."
  exit 1
fi
say "${GREEN}✓${RESET} gh is signed in, this is $REPO, and the Tauri CLI is installed."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
say "This certificate signs Plumo so macOS knows who made it."
IDENTITY="$(_identity)"
if [[ -n "$IDENTITY" ]]; then
  say "${GREEN}✓${RESET} Found in your keychain: $IDENTITY"
else
  say "Your keychain has no Developer ID Application certificate yet. Make one:"
  step "Open Keychain Access. In the menu bar: Keychain Access → Certificate Assistant →"
  say "  Request a Certificate From a Certificate Authority…"
  step "Enter your email and name, leave CA Email empty, choose 'Saved to disk', Continue."
  say "  This saves a .certSigningRequest file."
  pause "Press Enter when the request file is saved"
  open_url "https://developer.apple.com/account/resources/certificates/add"
  step "Under Software, choose 'Developer ID Application', Continue."
  step "Keep the newest profile type (G2 Sub-CA), upload the .certSigningRequest file, Continue."
  step "Download the .cer file and double-click it to add it to the login keychain."
  note "Only the Account Holder of the developer team can create this certificate."
  while true; do
    pause "Press Enter when the certificate is installed"
    IDENTITY="$(_identity)"
    [[ -n "$IDENTITY" ]] && break
    warn "Still no Developer ID Application certificate with its private key in the keychain."
  done
  say "${GREEN}✓${RESET} Found: $IDENTITY"
fi
set_secret APPLE_SIGNING_IDENTITY "$IDENTITY"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Export the certificate for CI"
say "GitHub Actions needs the certificate and its private key as one .p12 file."
step "In Keychain Access, pick the 'login' keychain and the 'My Certificates' tab."
step "Right-click '$IDENTITY' → Export…"
step "File format: Personal Information Exchange (.p12). Save it to the Desktop as"
say "  plumo-developer-id.p12, and give it a password you make up now."
note "macOS then asks for your login password to allow the export."
_ask_file P12_PATH "Path to the .p12 file:" "$HOME/Desktop/plumo-developer-id.p12"
ask_secret P12_PASSWORD "The password you gave the .p12:"
if openssl pkcs12 -in "$P12_PATH" -passin "pass:$P12_PASSWORD" -nokeys -legacy >/dev/null 2>&1 \
  || openssl pkcs12 -in "$P12_PATH" -passin "pass:$P12_PASSWORD" -nokeys >/dev/null 2>&1; then
  say "${GREEN}✓${RESET} The password opens the file."
else
  warn "Could not open the .p12 with that password. If you are sure it is right, continue;"
  warn "otherwise press Ctrl-C and run the wizard again."
  pause
fi
set_secret APPLE_CERTIFICATE "$(base64 < "$P12_PATH" | tr -d '\n')"
set_secret APPLE_CERTIFICATE_PASSWORD "$P12_PASSWORD"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (notarization)"
say "Apple checks each build for malware before macOS will open it. CI submits the"
say "build with this key, which is separate from your Apple ID password."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "On Users and Access → Integrations → App Store Connect API, open 'Team Keys'."
step "Click + to generate a key. Name: Plumo notarization. Access: Developer."
step "Copy the Issuer ID shown above the list of keys."
ask APPLE_API_ISSUER "Paste the Issuer ID:"
step "Copy the Key ID from the new key's row."
ask APPLE_API_KEY "Paste the Key ID:"
step "Click 'Download' on that row. Apple lets you download the .p8 file only once."
note "If the page looks different from these steps, stop and tell Claude what you see."
_ask_file P8_PATH "Path to the .p8 file:" "$HOME/Downloads/AuthKey_${APPLE_API_KEY}.p8"
set_secret APPLE_API_ISSUER "$APPLE_API_ISSUER"
set_secret APPLE_API_KEY "$APPLE_API_KEY"
set_secret APPLE_API_KEY_P8 "$(cat "$P8_PATH")"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Updater signing key"
say "Each Update is signed with this key, and Plumo refuses one that is not."
warn "If this key is lost, installed copies of Plumo can never update again."
warn "If it leaks, someone else can sign an Update. Keep it in your password manager."
if [[ -f "$UPDATER_KEY_PATH" ]]; then
  say "A key already exists at $UPDATER_KEY_PATH; it is kept."
else
  say "The Tauri CLI now asks you to choose a password for the key, twice."
  mkdir -p "$(dirname "$UPDATER_KEY_PATH")"
  node_modules/.bin/tauri signer generate -w "$UPDATER_KEY_PATH"
fi
ask_secret UPDATER_KEY_PASSWORD "Type the key's password once more, to store it for CI:"
set_secret TAURI_SIGNING_PRIVATE_KEY "$(cat "$UPDATER_KEY_PATH")"
set_secret TAURI_SIGNING_PRIVATE_KEY_PASSWORD "$UPDATER_KEY_PASSWORD"
UPDATER_PUBKEY="$(cat "$UPDATER_KEY_PATH.pub")" node -e '
  const fs = require("fs")
  const path = "src-tauri/tauri.conf.json"
  const config = JSON.parse(fs.readFileSync(path, "utf8"))
  config.plugins.updater.pubkey = process.env.UPDATER_PUBKEY.trim()
  fs.writeFileSync(path, fs.readFileSync(path, "utf8").replace(/"pubkey": "[^"]*"/, `"pubkey": ${JSON.stringify(config.plugins.updater.pubkey)}`))
'
say "${GREEN}✓${RESET} wrote the public key into src-tauri/tauri.conf.json (it is safe to commit)."
step "Now save two things in your password manager:"
say "  the contents of $UPDATER_KEY_PATH, and the password you chose."
until confirm "Are the private key and its password saved in your password manager?"; do
  warn "Save them before going on; GitHub will not show the secret again."
done

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Tidy up"
say "The secrets are in GitHub now. The copies on disk are no longer needed by CI:"
step "Move $P8_PATH into your password manager, then delete the file."
step "Delete $P12_PATH (the certificate stays in your keychain)."
step "Keep $UPDATER_KEY_PATH only if your password manager has it too."
say "Then commit the change to src-tauri/tauri.conf.json, or tell Claude it is there."
pause

finish
}

run_wizard "$@"; exit
